1	import React, { useEffect, useRef, useState } from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { defineMessages, useIntl } from 'react-intl';
4	import { ZimmSlideIndicator } from '../zimmSlideIndicator';
5	import { ChevronLeftIcon, ChevronRightIcon, CloseIcon } from '../../../icons';
6	
7	/**
8	 * Selector contract for a later step (the ZimmProductCard organism, SFCC-236 Step 6): stable
9	 * `data-card-slot` values on this component's own DOM so that organism's own recipe can target
10	 * these descendants for hover-reveal styling without reaching into implementation details.
11	 * Do not rename these values without updating that recipe too:
12	 *   - "media"     — the outermost element (this component's root)
13	 *   - "close"     — the remove-CTA button (present only when `onRemove` + a usable label exist)
14	 *   - "carousel"  — the prev/next arrows wrapper (present only when paging is enabled)
15	 *   - "indicator" — the touch slide-indicator wrapper (present only when there is >1 image)
16	 */
17	
18	const messages = defineMessages({
19	  previousImage: { id: 'product_card_media.pagination.previous', defaultMessage: 'Previous image' },
20	  nextImage: { id: 'product_card_media.pagination.next', defaultMessage: 'Next image' },
21	  /**
22	   * Accessible name for the always-available keyboard-operable scroll container (WCAG 2.1.1) —
23	   * distinct from the hover-capable-only `carousel` arrows and the touch-only
24	   * `indicatorWrapper`, this is the underlying paging affordance that exists regardless of
25	   * pointer capability. See `canNavigateByKeyboard` below.
26	   */
27	  galleryLabel: { id: 'product_card_media.gallery.label', defaultMessage: 'Product images' },
28	});
29	
30	const ZIMM_PRODUCT_CARD_MEDIA_RECIPE = 'ZimmProductCardMedia';
31	
32	/** One image the card can show — always a real, non-empty product-photo description. */
33	export type ZimmProductCardMediaImage = {
34	  src: string;
35	  alt: string;
36	};
37	
38	export type ZimmProductCardMediaProps = {
39	  /** The image shown when nothing else applies — always required, even when `images` is supplied. */
40	  primaryImage: ZimmProductCardMediaImage;
41	  /**
42	   * The second image revealed on hover (desktop/hover-capable pointers only), crossfading with
43	   * `primaryImage`. Ignored while a multi-image `images` gallery is active (>1 entries) — the
44	   * arrows/indicator paging affordances already give a shopper a way to browse every image, so
45	   * a hover-swap of just the first two would be a second, inconsistent way to see the same
46	   * content. Has no effect unless `swapOnHover` is also true.
47	   */
48	  hoverImage?: ZimmProductCardMediaImage;
49	  /**
50	   * The full orderable gallery for this card. Only takes over from `primaryImage` when it has
51	   * more than one entry — 0 or 1 entries behaves exactly like an absent `images` (see
52	   * `hoverImage`'s note above for why the two features don't combine).
53	   */
54	  images?: ZimmProductCardMediaImage[];
55	  /** Enables the primary/hover crossfade described on `hoverImage`. Has no effect without it. */
56	  swapOnHover: boolean;
57	  /**
58	   * Enables the desktop prev/next arrows. The touch slide-indicator is independent of this flag
59	   * (per the Figma "Image Group" spec, the touch variant has no separate "controls off" state)
60	   * — it renders whenever there is more than one image to page through, regardless of this prop.
61	   */
62	  showControls: boolean;
63	  /** Wishlist-only remove action. Rendered only when paired with a usable `removeLabel`. */
64	  onRemove?: () => void;
65	  /**
66	   * Accessible name for the remove button — required in practice whenever `onRemove` is passed
67	   * (typically the product name, e.g. "Remove {productName} from wishlist"). Modelled as two
68	   * independent optional props rather than a discriminated union because this is a simple
69	   * co-requirement, not a real variant split: if `onRemove` is supplied without a usable
70	   * (non-empty, non-whitespace) `removeLabel`, the remove button silently does not render at
71	   * all rather than shipping an unlabelled, inaccessible button — see the component body.
72	   */
73	  removeLabel?: string;
74	  /**
75	   * LCP escape hatch for the primary image slot. Defaults to lazy-loading — this component has
76	   * no way to know whether it sits above the fold, so the safer default is lazy; a caller that
77	   * knows it renders above the fold (AGENTS.md's "LCP ≤2s p75 mobile" priority) should pass
78	   * `priority`. Has no effect on any non-primary image, which is always lazy regardless.
79	   */
80	  priority?: boolean;
81	};
82	
83	/**
84	 * Molecule — the product-card media block: a single image, a hover-swap pair, or a full
85	 * scroll-snap gallery with desktop arrows / touch slide-indicator, plus the wishlist-remove
86	 * overlay slot. Figma "Image Group" component set, node 40002742:46323.
87	 *
88	 * Touch paging is native CSS scroll-snap at every breakpoint; arrows are a progressive
89	 * enhancement over the same scroll container, never a second, independent mechanism. Arrows and
90	 * the slide indicator are mutually exclusive by pointer capability
91	 * (`(hover: hover) and (pointer: fine)`) and never both interactively visible at once. Both
92	 * exist in the DOM at all times and are gated by the recipe's own CSS media query rather than a
93	 * JS `window.matchMedia` check — matching the "keep in DOM, hide via CSS" precedent
94	 * `ZimmColourSwatchGroup` already uses for its off-page swatches — so server and client render
95	 * identically (no hydration mismatch) and neither affordance depends on `matchMedia`, which
96	 * jsdom (this component's own Vitest environment) does not implement.
97	 *
98	 * A third, always-available operability layer sits underneath both visual affordances: the
99	 * scroll container itself is keyboard-focusable and handles ArrowLeft/ArrowRight directly
100	 * whenever there is more than one slide, regardless of pointer capability or `showControls` —
101	 * a hover-incapable pointer previously had no way to page the gallery via keyboard at all
102	 * (WCAG 2.1.1), since the arrows are `display:none` there and the indicator has no focusable
103	 * content. See `canNavigateByKeyboard` / `handleScrollContainerKeyDown` below.
104	 */
105	export const ZimmProductCardMedia = ({
106	  primaryImage,
107	  hoverImage,
108	  images,
109	  swapOnHover,
110	  showControls,
111	  onRemove,
112	  removeLabel,
113	  priority,
114	}: ZimmProductCardMediaProps) => {
115	  const intl = useIntl();
116	  const styles = useMultiStyleConfig(ZIMM_PRODUCT_CARD_MEDIA_RECIPE, {});
117	
118	  // >1 entries takes over as the full slide list; 0 or 1 behaves like no gallery at all (see
119	  // the `images` prop's own JSDoc for why hover-swap and the gallery don't combine).
120	  const gallery = images && images.length > 1 ? images : undefined;
121	  const slideImages = gallery ?? [primaryImage];
122	  const totalSlides = slideImages.length;
123	  const showHoverSwap = swapOnHover && Boolean(hoverImage) && !gallery;
124	  const canPage = totalSlides > 1 && showControls;
125	  // Keyboard operability is independent of `showControls` — deliberately not folded into
126	  // `canPage` above (WCAG 2.1.1): a hover-incapable pointer (a touchscreen with a physical
127	  // keyboard attached, switch access, or a desktop browser reporting `hover:none`) has the
128	  // arrows hidden by the recipe's own media query and the indicator has no focusable content,
129	  // so this is the only paging affordance such a user has, regardless of `showControls`.
130	  const canNavigateByKeyboard = totalSlides > 1;
131	
132	  // Single piece of state, per this codebase's extract-to-hook threshold
133	  // (.claude/rules/components.md). Kept inline — including the scroll-tracking and
134	  // index-clamping effects below — rather than pulled into a useProductCardMediaScroll hook,
135	  // because this build step's file manifest is limited to this component's own 4 files; a hook
136	  // would be a 5th file outside that scope.
137	  const [currentIndex, setCurrentIndex] = useState(0);
138	  const scrollContainerRef = useRef<HTMLDivElement>(null);
139	
140	  const scrollToIndex = (index: number) => {
141	    const container = scrollContainerRef.current;
142	    if (!container || typeof container.scrollTo !== 'function') return;
143	    // clientWidth is 0 under jsdom (no real layout) — the call still fires with a plausible
144	    // {left, behavior} shape, which is what this component's own Vitest suite asserts; a real
145	    // browser reports a real width so the requested slide scrolls fully into view.
146	    container.scrollTo({ left: index * container.clientWidth, behavior: 'smooth' });
147	  };
148	
149	  const goToRelativeSlide = (delta: 1 | -1) => {
150	    if (totalSlides <= 1) return;
151	    const next = (currentIndex + delta + totalSlides) % totalSlides;
152	    setCurrentIndex(next);
153	    scrollToIndex(next);
154	  };
155	
156	  // Re-clamps currentIndex whenever the slide count shrinks while this instance stays mounted
157	  // (e.g. a colour-variant swap that reduces the gallery from 3 images to 2) — same "clamp to
158	  // the highest valid index" precedent as ZimmColourSwatchGroup's own page-clamp effect
159	  // (../zimmColourSwatchGroup/index.tsx:75-84). Without this, currentIndex stays at the stale,
160	  // out-of-range value: ZimmSlideIndicator's own display-side clamp masks it visually right
161	  // after the shrink, but goToRelativeSlide's modulo arithmetic above still computes from the
162	  // stale, unclamped state, so the very next Next/Previous click is a silent no-op.
163	  useEffect(() => {
164	    setCurrentIndex((index) => Math.min(index, totalSlides - 1));
165	  }, [totalSlides]);
166	
167	  // Arrow-key paging on the scroll container itself, reachable regardless of pointer
168	  // capability — additive to, and independent of, the hover-capable-only arrows and the
169	  // touch-only indicator above (see canNavigateByKeyboard's own comment for why). Same
170	  // "check the key, then preventDefault" idiom as ZimmColourSwatchGroup's own
171	  // handleSwatchesKeyDown (../zimmColourSwatchGroup/index.tsx:109-111).
172	  const handleScrollContainerKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
173	    if (!['ArrowLeft', 'ArrowRight'].includes(event.key)) return;
174	    event.preventDefault();
175	    goToRelativeSlide(event.key === 'ArrowRight' ? 1 : -1);
176	  };
177	
178	  // Keeps the touch slide-indicator's active dot following native swipe paging, which never
179	  // calls goToRelativeSlide at all. `scrollend` (Baseline 2024 — Chrome 114+, Firefox 109+,
180	  // Safari 18+) fires once the snap gesture settles. No `scroll`-event fallback for older
181	  // Safari: CSS scroll-snap paging itself is unaffected either way — the indicator dot simply
182	  // lags on an unsupported browser, a minor, graceful degradation rather than a broken
183	  // interaction.
184	  useEffect(() => {
185	    const container = scrollContainerRef.current;
186	    if (!container || totalSlides <= 1) return undefined;
187	
188	    const handleScrollEnd = () => {
189	      const slideWidth = container.clientWidth || 1;
190	      const nearest = Math.round(container.scrollLeft / slideWidth);
191	      setCurrentIndex(Math.min(Math.max(nearest, 0), totalSlides - 1));
192	    };
193	
194	    container.addEventListener('scrollend', handleScrollEnd);
195	    return () => container.removeEventListener('scrollend', handleScrollEnd);
196	  }, [totalSlides]);
197	
198	  // Non-primary images are always lazy; only the first slide's own base image can opt into
199	  // eager loading via `priority`. See that prop's own JSDoc for the default-to-lazy reasoning.
200	  const imageLoadingProps = (isPrimaryPosition: boolean): { loading?: 'lazy'; decoding: 'async' } =>
201	    isPrimaryPosition && priority ? { decoding: 'async' } : { loading: 'lazy', decoding: 'async' };
202	
203	  const hasUsableRemoveLabel = typeof removeLabel === 'string' && removeLabel.trim().length > 0;
204	  const showRemove = Boolean(onRemove) && hasUsableRemoveLabel;
205	
206	  return (
207	    <chakra.div __css={styles.root} data-card-slot="media">
208	      <chakra.div
209	        ref={scrollContainerRef}
210	        __css={styles.scrollContainer}
211	        data-testid="card-media-scroll"
212	        role={canNavigateByKeyboard ? 'group' : undefined}
213	        aria-label={canNavigateByKeyboard ? intl.formatMessage(messages.galleryLabel) : undefined}
214	        tabIndex={canNavigateByKeyboard ? 0 : undefined}
215	        onKeyDown={canNavigateByKeyboard ? handleScrollContainerKeyDown : undefined}
216	      >
217	        {slideImages.map((image, index) => {
218	          const isPrimaryPosition = index === 0;
219	
220	          if (isPrimaryPosition && showHoverSwap && hoverImage) {
221	            return (
222	              <chakra.div key={`${image.src}-${index}`} __css={styles.slide}>
223	                <chakra.img
224	                  src={image.src}
225	                  alt={image.alt}
226	                  data-role="hover-base"
227	                  __css={styles.hoverSwapBase}
228	                  {...imageLoadingProps(true)}
229	                />
230	                <chakra.img
231	                  src={hoverImage.src}
232	                  alt={hoverImage.alt}
233	                  data-role="hover-overlay"
234	                  __css={styles.hoverSwapOverlay}
235	                  {...imageLoadingProps(false)}
236	                />
237	              </chakra.div>
238	            );
239	          }
240	
241	          return (
242	            <chakra.div key={`${image.src}-${index}`} __css={styles.slide}>
243	              <chakra.img
244	                src={image.src}
245	                alt={image.alt}
246	                __css={styles.image}
247	                {...imageLoadingProps(isPrimaryPosition)}
248	              />
249	            </chakra.div>
250	          );
251	        })}
252	      </chakra.div>
253	
254	      {showRemove && (
255	        <chakra.button
256	          type="button"
257	          __css={styles.close}
258	          data-card-slot="close"
259	          aria-label={removeLabel}
260	          onClick={onRemove}
261	        >
262	          <CloseIcon aria-hidden />
263	        </chakra.button>
264	      )}
265	
266	      {canPage && (
267	        <chakra.div __css={styles.carousel} data-card-slot="carousel">
268	          <chakra.button
269	            type="button"
270	            __css={styles.arrowButton}
271	            aria-label={intl.formatMessage(messages.previousImage)}
272	            onClick={() => goToRelativeSlide(-1)}
273	          >
274	            <ChevronLeftIcon aria-hidden />
275	          </chakra.button>
276	          <chakra.button
277	            type="button"
278	            __css={styles.arrowButton}
279	            aria-label={intl.formatMessage(messages.nextImage)}
280	            onClick={() => goToRelativeSlide(1)}
281	          >
282	            <ChevronRightIcon aria-hidden />
283	          </chakra.button>
284	        </chakra.div>
285	      )}
286	
287	      {totalSlides > 1 && (
288	        <chakra.div __css={styles.indicatorWrapper} data-card-slot="indicator">
289	          <ZimmSlideIndicator count={totalSlides} activeIndex={currentIndex} />
290	        </chakra.div>
291	      )}
292	    </chakra.div>
293	  );
294	};
295	
296	export default ZimmProductCardMedia;
