1	/**
2	 * Scoped per testing.md: this component's own contract (given props, does it render the right
3	 * branch and wire the right handler) — not ZimmSlideIndicator's own segment/clamp logic, which
4	 * is proven in its own index.test.tsx and rendered here for real (it is a lightweight,
5	 * side-effect-free presentational atom, so composing it directly costs nothing and gives real
6	 * integration confidence that this component passes it the right `count`/`activeIndex`).
7	 */
8	import React from 'react';
9	import { describe, test, expect, vi } from 'vitest';
10	import { render, screen, fireEvent } from '@testing-library/react';
11	import userEvent from '@testing-library/user-event';
12	import { IntlProvider } from 'react-intl';
13	import { ZimmProductCardMedia } from './index';
14	import type { ZimmProductCardMediaImage } from './index';
15	import { ZimmProductCardMedia as ZimmProductCardMediaRecipe } from './zimmProductCardMedia.css';
16	
17	// Flat parts object covering both this component's own recipe AND ZimmSlideIndicator's
18	// (root/dot) — the same mocked useMultiStyleConfig is shared by both since neither test setup
19	// nor Chakra itself cares which recipe name asked for it. Same precedent as
20	// zimmSizeChipGroup/index.test.tsx's comment on its composed atom's unresolved styles.chip.
21	vi.mock('@chakra-ui/react', async (importOriginal) => {
22	  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
23	  return {
24	    ...actual,
25	    useMultiStyleConfig: () => ({
26	      root: {},
27	      scrollContainer: {},
28	      slide: {},
29	      image: {},
30	      hoverSwapBase: {},
31	      hoverSwapOverlay: {},
32	      close: {},
33	      carousel: {},
34	      arrowButton: {},
35	      indicatorWrapper: {},
36	      dot: {},
37	    }),
38	  };
39	});
40	
41	// ChevronLeftIcon / ChevronRightIcon / CloseIcon: the icons barrel has the Vitest SVG
42	// side-effect issue documented in .claude/rules/testing.md's "Known gap: ZimmIcon throws under
43	// Vitest" section. Mocked at the same relative specifier this component imports them from.
44	vi.mock('../../../icons', () => ({
45	  ChevronLeftIcon: () => null,
46	  ChevronRightIcon: () => null,
47	  CloseIcon: () => null,
48	}));
49	
50	const wrap = (ui: React.ReactElement) =>
51	  render(
52	    <IntlProvider locale="en" defaultLocale="en">
53	      {ui}
54	    </IntlProvider>,
55	  );
56	
57	const PRIMARY: ZimmProductCardMediaImage = { src: 'primary.jpg', alt: 'Zimmermann dress, front' };
58	const HOVER: ZimmProductCardMediaImage = { src: 'hover.jpg', alt: 'Zimmermann dress, on model' };
59	const GALLERY: ZimmProductCardMediaImage[] = [
60	  { src: 'g1.jpg', alt: 'Zimmermann dress, front' },
61	  { src: 'g2.jpg', alt: 'Zimmermann dress, side' },
62	  { src: 'g3.jpg', alt: 'Zimmermann dress, back' },
63	];
64	
65	/** Mocks the scroll container's native `scrollTo` (absent under jsdom — see index.tsx's own
66	 *  comment) so an arrow click can be asserted against a spy instead of throwing. */
67	const mockScrollTo = (): ReturnType<typeof vi.fn> => {
68	  // HTMLElement already types `scrollTo` (lib.dom.d.ts) — jsdom just doesn't implement it at
69	  // runtime, so a plain mock-function assignment is enough; no cast needed.
70	  const scrollContainer = screen.getByTestId('card-media-scroll');
71	  const scrollTo = vi.fn();
72	  scrollContainer.scrollTo = scrollTo;
73	  return scrollTo;
74	};
75	
76	describe('ZimmProductCardMedia — AC1: primary image renders with minimal props', () => {
77	  test('renders the primary image when hoverImage, images and showControls are all absent/false', () => {
78	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} />);
79	    const img = screen.getByRole('img', { name: PRIMARY.alt });
80	    expect(img).toHaveAttribute('src', PRIMARY.src);
81	  });
82	});
83	
84	describe('ZimmProductCardMedia — alt text', () => {
85	  test('every rendered gallery image carries its own meaningful alt text', () => {
86	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
87	    GALLERY.forEach((image) => {
88	      expect(screen.getByRole('img', { name: image.alt })).toBeInTheDocument();
89	    });
90	  });
91	
92	  test('a hover-swap pair keeps both images accessible by their own alt text', () => {
93	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} hoverImage={HOVER} swapOnHover showControls={false} />);
94	    expect(screen.getByRole('img', { name: PRIMARY.alt })).toBeInTheDocument();
95	    expect(screen.getByRole('img', { name: HOVER.alt })).toBeInTheDocument();
96	  });
97	});
98	
99	describe('ZimmProductCardMedia — lazy/eager loading', () => {
100	  test('the primary image lazy-loads by default (priority absent)', () => {
101	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} />);
102	    const img = screen.getByRole('img', { name: PRIMARY.alt });
103	    expect(img).toHaveAttribute('loading', 'lazy');
104	    expect(img).toHaveAttribute('decoding', 'async');
105	  });
106	
107	  test('the primary image loads eagerly when priority is true', () => {
108	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} priority />);
109	    const img = screen.getByRole('img', { name: PRIMARY.alt });
110	    expect(img).not.toHaveAttribute('loading');
111	    expect(img).toHaveAttribute('decoding', 'async');
112	  });
113	
114	  test('non-primary gallery images are always lazy, even when priority is true', () => {
115	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls priority />);
116	    expect(screen.getByRole('img', { name: GALLERY[0].alt })).not.toHaveAttribute('loading');
117	    expect(screen.getByRole('img', { name: GALLERY[1].alt })).toHaveAttribute('loading', 'lazy');
118	    expect(screen.getByRole('img', { name: GALLERY[2].alt })).toHaveAttribute('loading', 'lazy');
119	  });
120	
121	  test('the hover-swap overlay image is always lazy, even when priority is true', () => {
122	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} hoverImage={HOVER} swapOnHover showControls={false} priority />);
123	    expect(screen.getByRole('img', { name: PRIMARY.alt })).not.toHaveAttribute('loading');
124	    expect(screen.getByRole('img', { name: HOVER.alt })).toHaveAttribute('loading', 'lazy');
125	  });
126	});
127	
128	describe('ZimmProductCardMedia — single image renders no paging affordance', () => {
129	  test('renders no arrow buttons and no slide indicator, even when showControls is true', () => {
130	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls />);
131	    expect(screen.queryAllByRole('button')).toHaveLength(0);
132	    expect(screen.queryByRole('group')).not.toBeInTheDocument(); // ZimmSlideIndicator's role=group
133	  });
134	
135	  test('a 1-entry images array behaves identically to an absent images array', () => {
136	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={[GALLERY[0]]} swapOnHover={false} showControls />);
137	    expect(screen.queryAllByRole('button')).toHaveLength(0);
138	    expect(screen.queryByRole('group')).not.toBeInTheDocument();
139	  });
140	});
141	
142	describe('ZimmProductCardMedia — arrows wrap at both ends', () => {
143	  test('Next from the last image wraps to the first, updates the indicator, and calls scrollTo with a plausible shape', async () => {
144	    const user = userEvent.setup();
145	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
146	    const scrollTo = mockScrollTo();
147	
148	    const next = screen.getByRole('button', { name: 'Next image' });
149	    await user.click(next); // 0 -> 1
150	    await user.click(next); // 1 -> 2 (last)
151	    scrollTo.mockClear();
152	    await user.click(next); // wraps 2 -> 0
153	
154	    expect(scrollTo).toHaveBeenCalledTimes(1);
155	    // jsdom reports clientWidth as 0 regardless of index, so the numeric offset itself cannot
156	    // prove which slide was requested — only that a plausible {left, behavior} shape was sent.
157	    expect(scrollTo).toHaveBeenCalledWith(expect.objectContaining({ left: expect.any(Number), behavior: 'smooth' }));
158	    // The logical wrap is proven via the composed (real, unmocked) slide indicator's accessible
159	    // name, which reflects `activeIndex` from pure component state regardless of jsdom layout.
160	    expect(screen.getByRole('group', { name: 'Image 1 of 3' })).toBeInTheDocument();
161	  });
162	
163	  test('Previous from the first image wraps to the last, updates the indicator, and calls scrollTo with a plausible shape', async () => {
164	    const user = userEvent.setup();
165	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
166	    const scrollTo = mockScrollTo();
167	
168	    const previous = screen.getByRole('button', { name: 'Previous image' });
169	    await user.click(previous); // wraps 0 -> 2 (last)
170	
171	    expect(scrollTo).toHaveBeenCalledTimes(1);
172	    expect(scrollTo).toHaveBeenCalledWith(expect.objectContaining({ left: expect.any(Number), behavior: 'smooth' }));
173	    expect(screen.getByRole('group', { name: 'Image 3 of 3' })).toBeInTheDocument();
174	  });
175	});
176	
177	describe('ZimmProductCardMedia — remove (close) overlay', () => {
178	  test('renders nothing when onRemove is absent', () => {
179	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} />);
180	    expect(document.querySelector('[data-card-slot="close"]')).not.toBeInTheDocument();
181	  });
182	
183	  test('renders nothing when onRemove is supplied without a usable removeLabel (defensive no-op)', () => {
184	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} onRemove={vi.fn()} />);
185	    expect(document.querySelector('[data-card-slot="close"]')).not.toBeInTheDocument();
186	  });
187	
