 * "Type" variants of the size-chip Figma component set (node 40003066:34868):
 *   - `radiogroup` — the multi-size row (the default Type, 208x28 in Figma) — lays out
 *     ZimmSizeChip atoms in a row; each chip's own fill/border/focus styling stays in the
 *     sibling ZimmSizeChip atom's own recipe, this part is layout only.
 *   - `oneSize` — the single non-interactive label shown when only one size is offered (the
 *     other Type, 65x28 in Figma) — a genuinely different, non-interactive component, not a
 *     radiogroup with one item.
 */
export const ZimmSizeChipGroup = {
  parts: ['radiogroup', 'oneSize'],
  baseStyle: (): Record<string, SystemStyleObject> => ({
    radiogroup: {
      display: 'flex',
