    },

    oneSize: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      // The non-interactive single-label footprint from the size-chip Figma component set's
      // other Type — no matching width-scale token for 65px; height reuses the same
      // --zimm-scale-700 (28px) the ZimmSizeChip atom's own `chip` part uses, since it is the
      // same row height as the interactive variant.
      // audit-allow: 65px — no foundation width token exists for this exact non-interactive
      // label size
      width: '65px',
      height: 'var(--zimm-scale-700)',
      textStyle: 'buttonSm',
      color: 'var(--zimm-color-text-default)',
